#define _STLP_USE_NEWALLOC 1
#define _STLP_NO_EXCEPTIONS 1
#include <hash_map>

typedef int ObjectID;
typedef bool Bool;

class DamageInfo;
class BfmeSlavedUpdateInterface
{
public:
	virtual void slot00();
	virtual void slot04();
	virtual void onSlaverDie(const DamageInfo *);
};

template<int N>
class BfmeDeathSlots : public BfmeDeathSlots<N - 1>
{
public:
	virtual void slot(char (*)[N]);
};
template<> class BfmeDeathSlots<0> {};

class BfmeDeathBehaviorInterface : public BfmeDeathSlots<25>
{
public:
	virtual BfmeSlavedUpdateInterface *getSlavedUpdateInterface();
};

class Object
{
public:
	void setProducer(const Object *);
	void kill(int damageType, int deathType);
	unsigned char m_pad000[0x1f0];
	void **m_modules;
	unsigned char m_pad1f4[0x344 - 0x1f4];
	unsigned char m_deathFlags;
};

class BfmeDeathLookupLogic
{
public:
	Object *findObjectByID(ObjectID id);
};

class BfmeDieMuxData
{
public:
	bool isDieApplicable(const Object *, const DamageInfo *) const;
};

class Object;

typedef _STL::hash_map<ObjectID, Object *, _STL::hash<ObjectID>, _STL::equal_to<ObjectID> > ObjectPtrHash;

class GameLogic
{
public:
	__forceinline Object *findObjectByID(ObjectID id)
	{
		if (id == 0)
			return 0;

		ObjectPtrHash::iterator it = m_objHash.find(id);
		if (it == m_objHash.end())
			return 0;

		return (*it).second;
	}

	void destroyObject(Object *object);

private:
	char m_pad00[0xb0];
	ObjectPtrHash m_objHash;
};

class SpawnBehaviorModuleData
{
public:
	char m_pad00[0x18];
	Bool m_spawnedRequireSpawner;
	unsigned char m_pad19[0x2c - 0x19];
	BfmeDieMuxData m_dieMuxData;
};

struct SpawnIDNode
{
	SpawnIDNode *next;
	SpawnIDNode *previous;
	ObjectID value;
};
class SpawnBehavior
{
public:
	virtual void onDelete();
	virtual void onDie(const DamageInfo *);

private:
	char m_pad00[0x48];
	SpawnIDNode *m_spawnIDs;
};

#define TheGameLogic (*(GameLogic **)0x012f0898)

#pragma comment(linker, "/alternatename:?destroyObject@GameLogic@@QAEXPAVObject@@@Z=?j_0001d0de@@YAXXZ")
#pragma comment(linker, "/alternatename:?findObjectByID@BfmeDeathLookupLogic@@QAEPAVObject@@H@Z=?j_0001f253@@YAXXZ")
#pragma comment(linker, "/alternatename:?isDieApplicable@BfmeDieMuxData@@QBE_NPBVObject@@PBVDamageInfo@@@Z=?j_000357d8@@YAXXZ")


void SpawnBehavior::onDelete()
{
	SpawnBehaviorModuleData *moduleData = *(SpawnBehaviorModuleData **)((char *)this + 4);
	if (!moduleData->m_spawnedRequireSpawner)
		return;

	SpawnIDNode *entry = (*(SpawnIDNode **)((char *)this + 0x48))->next;
	if (entry == *(SpawnIDNode **)((char *)this + 0x48))
		return;

	GameLogic *logic = TheGameLogic;
	while (entry != *(SpawnIDNode **)((char *)this + 0x48))
	{
		Object *object = logic->findObjectByID(entry->value);
		entry = entry->next;
		if (object && ((*(unsigned char *)((char *)object + 0x344) & 1) == 0))
		{
			logic->destroyObject(object);
			logic = TheGameLogic;
		}
	}
}

void SpawnBehavior::onDie(const DamageInfo *damageInfo)
{
	// onDie receives the DieModule subobject at +0x24 of SpawnBehavior.
	SpawnBehaviorModuleData *moduleData = *(SpawnBehaviorModuleData **)((char *)this - 0x20);
	Object *owner = *(Object **)((char *)this - 0x1c);
	if (!moduleData->m_dieMuxData.isDieApplicable(owner, damageInfo))
		return;

	SpawnIDNode *head = *(SpawnIDNode **)((char *)this + 0x24);
	for (SpawnIDNode *iter = head->next; iter != head; iter = iter->next)
	{
		Object *spawn = ((BfmeDeathLookupLogic *)TheGameLogic)->findObjectByID(iter->value);
		if (!spawn)
			continue;
		void **module = (void **)spawn->m_modules;
		while (*module)
		{
			BfmeSlavedUpdateInterface *slave = ((BfmeDeathBehaviorInterface *)((char *)*module + 0xc))->getSlavedUpdateInterface();
			if (slave)
			{
				slave->onSlaverDie(damageInfo);
				break;
			}
			++module;
		}
		spawn->setProducer(0);
	}

	if (moduleData->m_spawnedRequireSpawner)
	{
		SpawnIDNode *head = *(SpawnIDNode **)((char *)this + 0x24);
		for (SpawnIDNode *iter = head->next; iter != head;)
		{
			Object *spawn = TheGameLogic->findObjectByID(iter->value);
			iter = iter->next;
			if (spawn && !(spawn->m_deathFlags & 1))
				spawn->kill(8, 0);
		}
	}
}
